source='''def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    from collections import Counter
    bg = Counter(v for row in g for v in row).most_common(1)[0][0]

    def edge_run(side):
        if side == 'top':
            vals = g[0]; pos = lambda k: (0, k)
        elif side == 'bottom':
            vals = g[h-1]; pos = lambda k: (h-1, k)
        elif side == 'left':
            vals = [g[r][0] for r in range(h)]; pos = lambda k: (k, 0)
        else:
            vals = [g[r][w-1] for r in range(h)]; pos = lambda k: (k, w-1)
        runs=[]; i=0
        while i<len(vals):
            if vals[i]==bg: i+=1; continue
            a=i; color=vals[i]
            while i<len(vals) and vals[i]==color: i+=1
            runs.append((a,i,color))
        if not runs: return None
        a,b,color=max(runs,key=lambda t:t[1]-t[0])
        return (side,a,b,color)

    # The paired edge bars define corresponding lanes by offset along the bars.
    tb1,tb2=edge_run('top'),edge_run('bottom')
    lr1,lr2=edge_run('left'),edge_run('right')
    if tb1 and tb2 and tb1[3]==tb2[3]:
        bars=(tb1,tb2); axis='vertical'
    elif lr1 and lr2 and lr1[3]==lr2[3]:
        bars=(lr1,lr2); axis='horizontal'
    else:
        return g
    marker=set()
    for side,a,b,color in bars:
        for k in range(a,b):
            marker.add((0,k) if side=='top' else (h-1,k) if side=='bottom' else (k,0) if side=='left' else (k,w-1))
    points=[(r,c,g[r][c]) for r in range(h) for c in range(w) if g[r][c]!=bg and (r,c) not in marker]
    if not points: return g
    # Map each point's position within one edge bar to the same offset on its opposite bar.
    if axis=='vertical':
        near={'top':bars[0], 'bottom':bars[1]}
        for r,c,col in points:
            lane=c
            match=next((bar for bar in bars if bar[1]<=lane<bar[2]),None)
            if match is None: continue
            side,a,b,_=match; off=lane-a
            other=bars[1] if match is bars[0] else bars[0]
            other_side,oa,ob,_=other
            paired=oa+off
            # Paint inward from the point's own edge, stopping before the point.
            if side=='top':
                for rr in range(1,r): g[rr][c]=col
            else:
                for rr in range(h-2,r,-1): g[rr][c]=col
            # The corresponding lane on the far marker is carried across the grid.
            if other_side=='bottom':
                for rr in range(h-2,-1,-1): g[rr][paired]=col
            else:
                for rr in range(1,h-1): g[rr][paired]=col
    else:
        for r,c,col in points:
            lane=r
            match=next((bar for bar in bars if bar[1]<=lane<bar[2]),None)
            if match is None: continue
            side,a,b,_=match; off=lane-a
            other=bars[1] if match is bars[0] else bars[0]
            other_side,oa,ob,_=other
            paired=oa+off
            if side=='left':
                for cc in range(1,c): g[r][cc]=col
            else:
                for cc in range(w-2,c,-1): g[r][cc]=col
            if other_side=='right':
                for cc in range(w-2,-1,-1): g[paired][cc]=col
            else:
                for cc in range(1,w-1): g[paired][cc]=col
    for r,c,col in points: g[r][c]=4
    return g
'''
